def noise_runs(grid, rects):
    mask=[[True]*30 for _ in range(30)]
    for c,i,j,h,w in rects:
        for r in range(i,i+h):
            for cc in range(j,j+w): mask[r][cc]=False
    runs=[]
    for i,row in enumerate(grid):
        for v,gr in groupby(row):
            L=len(list(gr))
            if mask[i][row.index(v) if False else 0]: pass
        # recompute respecting mask: split by mask
        cur=None; L=0
        for x in range(30):
            if not mask[i][x]:
                if cur is not None: runs.append((cur,L)); cur=None
                continue
            if row[x]==cur: L+=1
            else:
                if cur is not None: runs.append((cur,L))
                cur=row[x]; L=1
        if cur is not None: runs.append((cur,L))
    return runs
