def max_rects(grid, mind=3):
    out=[]
    for r in range(30):
        for c in range(30):
            v=grid[r][c]
            if (r>0 and grid[r-1][c]==v) or (c>0 and grid[r][c-1]==v):
                continue  # not top-left of any maximal rect... (only valid if same-color above/left ⇒ this cell inside a rect starting earlier) -- true for solid regions
            hh=0
            while r+hh<30 and grid[r+hh][c]==v: hh+=1
            ww=0
            while c+ww<30 and grid[r][c+ww]==v: ww+=1
            for h in range(mind,hh+1):
                w=0
                while w<ww and all(grid[r+i][c+w]==v for i in range(h)): w+=1
                for W in range(mind,w+1):
                    down = r+h<30 and all(grid[r+h][c+i]==v for i in range(W))
                    right = c+W<30 and all(grid[r+i][c+W]==v for i in range(h))
                    if not down and not right:
                        out.append((v,r,c,h,W))
    return out
